select pg_temp.denied('origin team cannot bypass private source-game visibility',format('select public.boss_team_season_read(%L::jsonb)',jsonb_build_object('organization_id',pg_temp.f('org'),'team_id',pg_temp.f('falcons'),'season_id',pg_temp.f('season'),'sport_key','baseball')),'PT403');
reset role;
update public.organization_modules set configuration=jsonb_set(configuration,'{baseball_stats}','false')where organization_id=pg_temp.f('org')and module_id=(select id from public.modules where key='sports');
set local role authenticated;select pg_temp.actor('admin');
select pg_temp.denied('disabled sport statistics cannot be bypassed by team aggregate',format('select public.boss_team_season_read(%L::jsonb)',jsonb_build_object('organization_id',pg_temp.f('org'),'team_id',pg_temp.f('falcons'),'season_id',pg_temp.f('season'),'sport_key','baseball')),'PT403');
reset role;
update public.organization_modules set configuration=jsonb_set(configuration,'{baseball_stats}','true')where organization_id=pg_temp.f('org')and module_id=(select id from public.modules where key='sports');
set local role authenticated;select pg_temp.actor('admin');
select pg_temp.denied('null rebuild kind rejected before work',format('select public.boss_stat_rebuild(%L::jsonb,null)',jsonb_build_object('organization_id',pg_temp.f('org'),'team_id',pg_temp.f('falcons'),'season_id',pg_temp.f('season'),'sport_key','baseball')),'PT422');
